using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class CaptureOptimizedTrees {
 static void Shot(Camera c,Vector3 pos,Vector3 target,float fov,string path){var oldPos=c.transform.position;var oldRot=c.transform.rotation;float oldFov=c.fieldOfView;var oldTarget=c.targetTexture;var oldActive=RenderTexture.active;var rt=RenderTexture.GetTemporary(1200,850,24);Texture2D tex=null;try{c.transform.SetPositionAndRotation(pos,Quaternion.LookRotation(target-pos));c.fieldOfView=fov;c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1200,850,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1200,850),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());}finally{c.transform.SetPositionAndRotation(oldPos,oldRot);c.fieldOfView=oldFov;c.targetTexture=oldTarget;RenderTexture.active=oldActive;RenderTexture.ReleaseTemporary(rt);if(tex)UnityEngine.Object.DestroyImmediate(tex);}}
 public static string Main(){var c=SceneView.lastActiveSceneView.camera;var root=GameObject.Find("New_Map").transform;var tree=root.GetComponentsInChildren<LODGroup>().Where(l=>l.name.StartsWith("TFP_Beech_Tree_02A")).OrderBy(l=>new Vector2(l.transform.position.x-45,l.transform.position.z-110).sqrMagnitude).First();var p=tree.transform.position;Shot(c,p+new Vector3(12,5,16),p+Vector3.up*5,52,"output/TreeOptimization/NearTree.png");Shot(c,new Vector3(0,10,65),new Vector3(0,27,314),58,"output/TreeOptimization/DistantHills.png");return "Nearby and distant tree previews captured; Editor view restored";}
}
